function getPowerUpStop(){return Math.round(powerUpBlockDiv.offsetLeft+.5*powerUpBlockDiv.offsetWidth-.5*containerDiv.offsetWidth)}function handlePowerUp(){var{position:e,delta:t}=scrollState;return!(ale.isShaved||e-getPowerUpStop()<=cutsceneCrossTolerance||(Math.abs(t)>containerDiv.offsetWidth?(usePowerUp(),1):t<=0||(hitPowerUpBlock(),0)))}function hitPowerUpBlock(){let t=gameConfig.powerUp,e=gameConfig.ale.frames,o=getPowerUpStop(),r=containerDiv.offsetHeight-groundAndGrassContainer1Div.offsetTop;var s=containerDiv.offsetHeight-powerUpBlockDiv.offsetTop-powerUpBlockDiv.offsetHeight;let a=powerUpBlockDiv.offsetHeight,i=s-t.aleJumpReach,p=r+t.aleHeadTop-s;startCutscene(1,o+t.stepDistance,[settleAle(o,r),{duration:t.jumpDuration,start:()=>setAleFrame(e.jumpUp),frame:e=>setAleBottom(r+(i-r)*cutsceneEaseOut(e))},{duration:t.fallDuration,start:()=>{powerUpBlockDiv.classList.add("power-up-used"),setAleFrame(e.jumpDown)},frame:e=>{setAleBottom(i+(r-i)*cutsceneEaseIn(e)),powerUpBlockDiv.style.transform=`translateY(${-t.bumpHeight*Math.sin(Math.PI*e)}px)`,1===e&&setAleStaticFrame()}},{duration:t.riseDuration,start:()=>{powerUpMushroomDiv.style.visibility="visible"},frame:e=>placeMushroom(0,a*e)},{duration:t.stepDuration,frame:e=>{placeMushroom(t.stepDistance*e,a),walkAle(o,o+t.stepDistance,e,t.stepDuration)}},{duration:t.dropDuration,frame:e=>placeMushroom(t.stepDistance,a+(p-a)*cutsceneEaseIn(e))},{duration:t.growDuration,start:()=>{powerUpMushroomDiv.style.visibility="hidden"},frame:e=>setAleShaved(1===e||Math.floor(e*t.growDuration/t.growFlickerInterval)%2==1)}],usePowerUp)}function usePowerUp(){setAleShaved(ale.isShaved=!0),powerUpBlockDiv.classList.add("power-up-used"),powerUpBlockDiv.style.transform="",powerUpMushroomDiv.style.visibility="hidden"}function setAleShaved(e){aleDiv.classList.toggle("ale-shaved",e)}function placeMushroom(e,t){powerUpMushroomDiv.style.transform=`translate(${e}px, ${-t}px)`}